{
  "constraints": [
    {
      "constraint": "画面若表现神舟十八号飞船的完整飞行器构型，则整体必须可辨识为轨道舱、返回舱、推进舱三舱串联结构，而不是单一舱段。",
      "polarity": "must_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "画面若表现神舟十八号飞船的完整飞行器构型，则返回舱必须位于轨道舱与推进舱之间。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "画面若表现神舟十八号飞船的完整飞行器构型，则返回舱必须呈钟形/钝头舱体外形。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "画面若表现神舟十八号飞船返回舱着陆，则不得呈现仍与返回舱相连的轨道舱和推进舱。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "desc"
    }
  ]
}
